class Collection(Entity):
    """Collection (core.Collection), schema version 1. A named set of entities, listed one by one or found by a search."""

    IKI_TYPE = 'core.Collection'

    entity = models.OneToOneField(
        Entity,
        models.PROTECT,
        parent_link=True,
        primary_key=True,
        db_column='entity_id',
        related_name='+',
    )
    name = models.CharField(max_length=200, db_index=True)
    description = models.TextField(null=True)
    search = models.JSONField(null=True)

    class Meta:
        db_table = 'core_collection'
        constraints = [
            models.CheckConstraint(
                condition=GreaterThanOrEqual(Length('name'), 1),
                name='core_collection__name__not_empty',
            ),
            models.CheckConstraint(
                condition=~Q(name__regex='[\\r\\n]'),
                name='core_collection__name__one_line',
            ),
            models.CheckConstraint(
                condition=GreaterThanOrEqual(Length('description'), 1),
                name='core_collection__description__not_empty',
            ),
            models.CheckConstraint(
                condition=LessThanOrEqual(Length('description'), 10000),
                name='core_collection__description__max_length',
            ),
        ]
        indexes = [
            GinIndex(
                fields=['name'],
                opclasses=['gin_trgm_ops'],
                name='name_trgm_ae92a16f0655134212ca',
            ),
            GinIndex(
                SearchVector('description', config='simple'),
                name='descriptio_fts_a79148c09b5a7a3',
            ),
        ]


class Collection_History(models.Model):
    """The history of core_collection: its values at each revision of each entity."""

    IKI_HISTORY_OF = 'Collection'
    APPEND_ONLY = True

    pk = models.CompositePrimaryKey('entity_id', 'revision')
    entity_id = models.UUIDField()
    revision = models.PositiveIntegerField()
    name = models.TextField(null=True)
    description = models.TextField(null=True)
    members = ArrayField(models.UUIDField(), null=True)
    search = models.JSONField(null=True)

    class Meta:
        db_table = 'core_collection__history'


class Collection_members(models.Model):
    """The items of core.Collection.members, in order."""

    IKI_LIST_OF = ('Collection', 'members')

    pk = models.CompositePrimaryKey('entity', 'position')
    entity = models.ForeignKey(
        'Collection',
        models.CASCADE,
        db_column='entity_id',
        related_name='+',
    )
    position = models.PositiveIntegerField()
    item = models.ForeignKey(Entity, models.PROTECT, related_name='+')

    class Meta:
        db_table = 'core_collection__members'
        constraints = [
            models.CheckConstraint(
                condition=Q(position__lt=10000),
                name='core_collection__members__position__max_items',
            ),
        ]
